parameterdescription.para:
キーを初期化するために使用される初期化ベクトルへのポインタ Example Aesenc;
intret=0;
bytekey[]={some16,24or32bytekey};
byteiv[]={some16byteiv};
if(ret=wc_AesSetKey(&enc,key,AES_BLOCK_SIZE,iv,
AES_ENCRYPTION)!=0){
//failedtosetaeskey
}

初期化ベクトルを設定するAES構造へのポインタ Example Aesenc;
//setenckey
byteiv[]={some16byteiv};
if(ret=wc_AesSetIV(&enc,iv)!=0){
//failedtosetaesiv
}

暗号化されるメッセージを含む入力バッファへのポインタ Example Aesenc;
intret=0;
//initializeencwithAesSetKey,usingdirectionAES_ENCRYPTION
bytemsg[AES_BLOCK_SIZE*n];//multipleof16bytes
//fillmsgwithdata
bytecipher[AES_BLOCK_SIZE*n];//Somemultipleof16bytes
if((ret=wc_AesCbcEncrypt(&enc,cipher,message,sizeof(msg)))!=0){
//blockalignerror
}

復号化する暗号テキストを含む入力バッファへのポインタ。 Example Aesdec;
intret=0;
//initializedecwithAesSetKey,usingdirectionAES_DECRYPTION
bytecipher[AES_BLOCK_SIZE*n];//somemultipleof16bytes
//fillcipherwithciphertext
byteplain[AES_BLOCK_SIZE*n];
if((ret=wc_AesCbcDecrypt(&dec,plain,cipher,sizeof(cipher)))!=0){
//blockalignerror
}

暗号化されるプレーンテキストを含む入力バッファへのポインタ Example Aesenc;
Aesdec;
//initializeencanddecwithAesSetKeyDirect,usingdirection
AES_ENCRYPTION
//sincetheunderlyingAPIonlycallsEncryptandbydefaultcalling
encrypton
//acipherresultsinadecryptionofthecipher

bytemsg[AES_BLOCK_SIZE*n];//nbeingapositiveintegermakingmsg
somemultipleof16bytes
//fillplainwithmessagetext
bytecipher[AES_BLOCK_SIZE*n];
bytedecrypted[AES_BLOCK_SIZE*n];
wc_AesCtrEncrypt(&enc,cipher,msg,sizeof(msg));//encryptplain
wc_AesCtrEncrypt(&dec,decrypted,cipher,sizeof(cipher));
//decryptciphertext

暗号化されたメッセージの暗号化テキストを保存する出力バッファへのポインタ Example Aesenc;
//initializeencwithAesSetKey,usingdirectionAES_ENCRYPTION
bytemsg[AES_BLOCK_SIZE];//16bytes
//initializemsgwithplaintexttoencrypt
bytecipher[AES_BLOCK_SIZE];
wc_AesEncryptDirect(&enc,cipher,msg);

復号化された暗号テキストのプレーンテキストを格納する出力バッファへのポインタ Example Aesdec;
//initializeencwithAesSetKey,usingdirectionAES_DECRYPTION
bytecipher[AES_BLOCK_SIZE];//16bytes
//initializecipherwithciphertexttodecrypt
bytemsg[AES_BLOCK_SIZE];
wc_AesDecryptDirect(&dec,msg,cipher);

キーを初期化するために使用される初期化ベクトル Example Aesenc;
intret=0;
bytekey[]={some16,24,or32bytekey};
byteiv[]={some16byteiv};
if(ret=wc_AesSetKeyDirect(&enc,key,sizeof(key),iv,
AES_ENCRYPTION)!=0){
//failedtosetaeskey
}

暗号化と復号化のための16,24、または32バイトの秘密鍵 Example Aesenc;
intret=0;
bytekey[]={some16,24,32bytekey};
if(ret=wc_AesGcmSetKey(&enc,key,sizeof(key))!=0){
//failedtosetaeskey
}

入力認証ベクトルを含むバッファへのポインタ Example Aesenc;
//initializeaesstructurebycallingwc_AesGcmSetKey

byteplain[AES_BLOCK_LENGTH*n];//nbeingapositiveinteger
makingplainsomemultipleof16bytes
//initializeplainwithmsgtoencrypt
bytecipher[sizeof(plain)];
byteiv[]=//some16byteiv
byteauthTag[AUTH_TAG_LENGTH];
byteauthIn[]=//AuthenticationVector

wc_AesGcmEncrypt(&enc,cipher,plain,sizeof(cipher),iv,sizeof(iv),
authTag,sizeof(authTag),authIn,sizeof(authIn));

入力認証ベクトルを含むバッファへのポインタ Example Aesenc;//canusethesamestructaswaspassedtowc_AesGcmEncrypt
//initializeaesstructurebycallingwc_AesGcmSetKeyifnotalreadydone

bytecipher[AES_BLOCK_LENGTH*n];//nbeingapositiveinteger
makingciphersomemultipleof16bytes
//initializecipherwithciphertexttodecrypt
byteoutput[sizeof(cipher)];
byteiv[]=//some16byteiv
byteauthTag[AUTH_TAG_LENGTH];
byteauthIn[]=//AuthenticationVector

wc_AesGcmDecrypt(&enc,output,cipher,sizeof(cipher),iv,sizeof(iv),
authTag,sizeof(authTag),authIn,sizeof(authIn));

認証のための16,24、または32バイトの秘密鍵 Example Gmacgmac;
key[]={some16,24,or32bytelengthkey};
wc_GmacSetKey(&gmac,key,sizeof(key));

GMACハッシュを保存する出力バッファへのポインタ Example Gmacgmac;
key[]={some16,24,or32bytelengthkey};
iv[]={some16bytelengthiv};

wc_GmacSetKey(&gmac,key,sizeof(key));
authIn[]={some16byteauthenticationinput};
tag[AES_BLOCK_SIZE];//willstoreauthenticationcode

wc_GmacUpdate(&gmac,iv,sizeof(iv),authIn,sizeof(authIn),tag,
sizeof(tag));

暗号化と復号化のための16,24、または32バイトの秘密鍵 Example Aesenc;
key[]={some16,24,or32bytelengthkey};

wc_AesCcmSetKey(&aes,key,sizeof(key));

入力認証ベクトルを含むバッファへのポインタ Example Aesenc;
//initializeencwithwc_AesCcmSetKey

nonce[]={initializenonce};
plain[]={someplaintextmessage};
cipher[sizeof(plain)];

authIn[]={some16byteauthenticationinput};
tag[AES_BLOCK_SIZE];//willstoreauthenticationcode

wc_AesCcmEncrypt(&enc,cipher,plain,sizeof(plain),nonce,sizeof(nonce),
tag,sizeof(tag),authIn,sizeof(authIn));

入力認証ベクトルを含むバッファへのポインタ Example Aesdec;
//initializedecwithwc_AesCcmSetKey

nonce[]={initializenonce};
cipher[]={encryptedmessage};
plain[sizeof(cipher)];

authIn[]={some16byteauthenticationinput};
tag[AES_BLOCK_SIZE]={authenticationtagreceivedforverification};

intreturn=wc_AesCcmDecrypt(&dec,plain,cipher,sizeof(cipher),
nonce,sizeof(nonce),tag,sizeof(tag),authIn,sizeof(authIn));
if(return!=0){
//decrypterror,invalidauthenticationcode
}

メモリに使用するヒントヒント。nullになることができます Example XtsAesaes;

if(wc_AesXtsSetKey(&aes,key,sizeof(key),AES_ENCRYPTION,NULL,0)!=0)
{
//Handleerror
}
wc_AesXtsFree(&aes);

両方ともバッファのサイズ Example XtsAesaes;
unsignedcharplain[SIZE];
unsignedcharcipher[SIZE];
word64s=VALUE;

//setupkeyswithAES_ENCRYPTIONasdir

if(wc_AesXtsEncryptSector(&aes,cipher,plain,SIZE,s)!=0)
{
//Handleerror
}
wc_AesXtsFree(&aes);

両方ともバッファのサイズ Example XtsAesaes;
unsignedcharplain[SIZE];
unsignedcharcipher[SIZE];
word64s=VALUE;

//setupaeskeywithAES_DECRYPTIONasdirandtweakwithAES_ENCRYPTION

if(wc_AesXtsDecryptSector(&aes,plain,cipher,SIZE,s)!=0)
{
//Handleerror
}
wc_AesXtsFree(&aes);

Tweakに使用する値 Example XtsAesaes;
unsignedcharplain[SIZE];
unsignedcharcipher[SIZE];
unsignedchari[AES_BLOCK_SIZE];

//setupkeywithAES_ENCRYPTIONasdir

if(wc_AesXtsEncrypt(&aes,cipher,plain,SIZE,i,sizeof(i))!=0)
{
//Handleerror
}
wc_AesXtsFree(&aes);

Tweakに使用する値 Example XtsAesaes;
unsignedcharplain[SIZE];
unsignedcharcipher[SIZE];
unsignedchari[AES_BLOCK_SIZE];

//setupkeywithAES_DECRYPTIONasdirandtweakwithAES_ENCRYPTION

if(wc_AesXtsDecrypt(&aes,plain,cipher,SIZE,i,sizeof(i))!=0)
{
//Handleerror
}
wc_AesXtsFree(&aes);

