S2VによるSIV出力（RFC 5297 2.4参照）。 Example bytekey[]={some32,48,or64bytekey};
byteassoc[]={0x01,0x2,0x3};
bytenonce[]={0x04,0x5,0x6};
byteplainText[]={0xDE,0xAD,0xBE,0xEF};
bytesiv[AES_BLOCK_SIZE];
bytecipherText[sizeof(plainText)];
if(wc_AesSivEncrypt(key,sizeof(key),assoc,sizeof(assoc),nonce,
sizeof(nonce),plainText,sizeof(plainText),siv,cipherText)!=0){
//failedtoencrypt
}

暗号文に付随するSIV（RFC 5297 2.4を参照）。 Example bytekey[]={some32,48,or64bytekey};
byteassoc[]={0x01,0x2,0x3};
bytenonce[]={0x04,0x5,0x6};
bytecipherText[]={0xDE,0xAD,0xBE,0xEF};
bytesiv[AES_BLOCK_SIZE]={theSIVthatcamewiththeciphertext};
byteplainText[sizeof(cipherText)];
if(wc_AesSivDecrypt(key,sizeof(key),assoc,sizeof(assoc),nonce,
sizeof(nonce),cipherText,sizeof(cipherText),siv,plainText)!=0){
//failedtodecrypt
}

復号化のための16,24、または32バイトの秘密鍵 Example intret=0;
bytekey[]={some16,24,or32bytekey};
byteiv[]={some16byteiv};
bytecipher[AES_BLOCK_SIZE*n];//nbeingapositiveintegermaking
ciphersomemultipleof16bytes
//fillcipherwithciphertext
byteplain[AES_BLOCK_SIZE*n];
if((ret=wc_AesCbcDecryptWithKey(plain,cipher,AES_BLOCK_SIZE,key,
AES_BLOCK_SIZE,iv))!=0){
//DecryptError
}
